// ════════════════════════════════════════════════════════════════════
// PLACEHOLDER MANIFEST GENERATOR — a consolidated, per-bank view of every
// contributor-facing field's placeholder, DERIVED from _data/grammar.yml (the
// single source the readiness widget also reads, via POLICY). So the manifest
// and the widget can never drift — both come from grammar.
//
// Writes _builder/PLACEHOLDERS.md (regenerated in `npm run gen`). To CHANGE a
// placeholder: edit the field's `blank:` in _data/grammar.yml, run `npm run
// gen`, and the manifest + the widget both update. Do NOT edit this file's
// output by hand.
// ════════════════════════════════════════════════════════════════════
import fs from 'node:fs';
import path from 'node:path';

const grammar = JSON.parse(fs.readFileSync(path.join(process.cwd(), 'data', 'grammar.json'), 'utf8'));
const ROOT = path.resolve(process.cwd(), '..');

function parseType(t) {
  if (typeof t !== 'string') return { kind: '?', label: '?' };
  const l = /^list<(.+)>$/.exec(t); if (l) return { kind: 'list', of: l[1], label: `list<${l[1]}>` };
  const e = /^enum\[(.*)\]$/.exec(t); if (e) return { kind: 'enum', values: e[1].split(',').map((s) => s.trim()), label: 'enum' };
  return { kind: t, label: t };
}

// classify the placeholder shown for a field
function placeholderOf(spec, t) {
  if (spec.seed_real) return '_(driver — real value, no placeholder)_';
  if (t.kind === 'enum') return '`' + (spec.default || t.values[0]) + '`  _(choice: ' + t.values.join(' · ') + ')_';
  if (spec.blank != null && typeof spec.blank !== 'object') return '`' + String(spec.blank) + '`';
  if (spec.item_blank != null && typeof spec.item_blank !== 'object') return '`' + String(spec.item_blank) + '`  _(per new item)_';
  if (spec.blank != null || spec.item_blank != null) return '_(template — see sub-fields)_';
  if (spec.default != null) return '`' + String(spec.default) + '`  _(default)_';
  return '—';
}

const out = [];
out.push('# Placeholder manifest', '');
out.push('> **Generated** from `_data/grammar.yml` by `npm run gen` — do not edit by hand.');
out.push('> This is the single source the readiness widget reads (via POLICY), so the manifest');
out.push('> and the widget always match. To change a placeholder, edit the field\'s `blank:` in');
out.push('> `_data/grammar.yml` and re-run `npm run gen`.', '');
out.push('Legend: **•** = required · _driver_ = a real value that positions the layout (no placeholder).', '');

function rows(fields, subs, prefix, depth, acc) {
  for (const [name, spec] of Object.entries(fields || {})) {
    if (!spec || typeof spec !== 'object' || spec.locked) continue;
    const t = parseType(spec.type);
    const rel = (prefix ? prefix + '.' : '') + name;
    const req = spec.required ? '•' : '';
    acc.push(`| \`${rel}\` | ${req} | ${t.label} | ${placeholderOf(spec, t)} |`);
    const sub = t.kind === 'list' ? subs[t.of] : subs[t.kind];
    if (sub && typeof sub === 'object') rows(sub, subs, rel + (t.kind === 'list' ? '[]' : ''), depth + 1, acc);
  }
}

let total = 0, withPh = 0;
for (const [comp, def] of Object.entries(grammar.components || {})) {
  if (!def || !def.fields) continue;
  out.push(`## ${comp}`, '');
  out.push('| Field | Req | Type | Placeholder |', '|---|---|---|---|');
  const acc = [];
  rows(def.fields, def.subtypes || {}, '', 0, acc);
  out.push(...acc, '');
  total += acc.length;
}

const md = out.join('\n') + '\n';
fs.writeFileSync(path.join(ROOT, 'PLACEHOLDERS.md'), md);
console.log(`placeholder manifest → PLACEHOLDERS.md (${total} fields across ${Object.keys(grammar.components || {}).length} banks)`);
